    }
    # Explicit negative facts. Closed-world reading: only these are denied.
    negfacts = {
        ("hugs", "ant", "flamingo"),
    }

    # Forward chaining to a fixpoint.
    changed = True
    while changed:
        changed = False
        new_pos, new_neg = set(), set()

        fish_names = [v for (t, e, v) in facts if t == "name" and e == "fish"]
        reindeer_names = [v for (t, e, v) in facts if t == "name" and e == "reindeer"]

        # Rule1: reindeer hugs crab if reindeer's name and fish's name share first letter.
        for r in reindeer_names:
            for f in fish_names:
                if r and f and r[0] == f[0]:
                    new_pos.add(("hugs", "reindeer", "crab"))

        # Rule2: whoever suspects the butterfly also suspects the otter.
        for (t, x, y) in list(facts):
