            new_neg.add(("hides", "otter", "dragon"))

        if not new_pos <= facts:
            facts |= new_pos
            changed = True
        if not new_neg <= negfacts:
            negfacts |= new_neg
            changed = True

    target_pos = ("hides", "otter", "dragon")
